ww.apache.org/licenses/LICENSE-2.0 # # Unless required by applicable law or agreed to in writing, software # distributed under the License is distributed on an "AS IS" BASIS, # WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied. # See the License for the specific language governing permissions and # limitations under the License. # # ISOFIT: Imaging Spectrometer Optimal FITting # Author: Niklas Bohn, urs.n.bohn@jpl.nasa.gov # Philip Brodrick, philip.brodrick@jpl.nasa.gov # Jouni Susiluoto, jouni.i.susiluoto@jpl.nasa.gov from __future__ import annotations import logging import h5py import numpy as np import yaml from isofit.core.common import combos , spectral_response_function from isofit.radiative_transfer.radiative_transfer_engine import RadiativeTransferEngine Logger = logging . getLogger ( __file__ ) # This is a tempoary key mapping until we align the KF and Isofit key names # and get KF to store the key names in the jld2 file KEYMAPPING = { 1 : { "name" : "AERFRAC_2" , "default" : 0.06 }, 2 : { "name" : "H2OSTR" , "default" : 0.2 }, 3 : { "name" : "surface_elevation_km" }, 4 : { "name" : "observer_altitude_km" }, 5 : { "name" : "solar_zenith" }, 6 : { "name" : "observer_zenith" }, 7 : { "name" : "relative_azimuth" }, 8 : { "name" : "solar_azimuth" }, 9 : { "name" : "observer_azimuth" }, } def bounds_check ( [docs] grid : dict , emulator_file : str = None , modify : bool = False , ): """Check if the grid points are within the bounds of the emulator Args: grid (dict): Dictionary of grid points emulator_file (str, optional): Path to the emulator file. Defaults to None. emulator (h5py.File, optional): Emulator file. Defaults to None. modify (bool, optional): If True, adjust the grid points to be within the bounds of the emulator. Defaults to False. Raises: ValueError: If grid points are out of bounds and modify == False """ if emulator_file : emulator = h5py . File ( emulator_file , "r" ) points_bound_min = emulator [ "xmin" ][:] points_bound_max = emulator [ "xmax" ][:] emulator_names = [ KEYMAPPING [ i ][ "name" ] for i in emulator [ "inputdims" ]] # convert observer zenith grid to MODTRAN convetion. if "observer_zenith" in grid . keys (): grid [ "observer_zenith" ] = [ 180 - x for x in grid [ "observer_zenith" ]] grid_errors = [] for _key , key in enumerate ( emulator_names ): if key in grid . keys (): oob_l = np . array ( grid [ key ]) < points_bound_min [ _key ] oob_h = np . array ( grid [ key ]) > points_bound_max [ _key ] if not modify and ( np . sum ( oob_h ) > 0 or np . sum ( oob_l ) > 0 ): grid_errors . append ( f "LUT grid { key } has out of bounds values. 
 values: { grid [ key ] } 
 RTM min: { points_bound_min [ _key ] } , RTM max: { points_bound_max [ _key ] } " ) if modify and np . sum ( oob_h ) > 0 : points = np . array ( grid [ key ]) prev_points = points . copy () points [ oob_h ] = points_bound_max [ _key ] grid [ key ] = np . unique ( points ) . tolist () logging . info ( f "LUT grid { key } has out of bounds values. Adjusting from { prev_points } to { points } ." ) if modify and np . sum ( oob_l ) > 0 : points = np . array ( grid [ key ]) prev_points = points . copy () points [ oob_l ] = points_bound_min [ _key ] grid [ key ] = np . unique ( points ) . tolist () logging . info ( f "LUT grid { key } has out of bounds values. Adjusting from { prev_points } to { points } ." ) if len ( grid_errors ) > 0 : grid_errors = " 
 " . join ( grid_errors ) raise ValueError ( grid_errors ) # back-convert observer zenith grid to MODTRAN convetion. if "observer_zenith" in grid . keys (): grid [ "observer_zenith" ] = [ 180 - x for x in grid [ "observer_zenith" ]] def predict_M ( [docs] M_Z , M_lambda , M_theta , M_h , points , G_Xproj_vectors , G_Xproj_values , G_Xmean , G_Xstd , ): Z_tr = M_Z . T # training inputs Z_te = reduce_points ( points , G_Xproj_vectors , G_Xproj_values , G_Xmean , G_Xstd ) Z_te = Z_te * M_lambda # scale test inputs theta = M_theta # RBF component to cross covariance matrix. Start by computing # Euclidean distances between testing and training inputs wb = np . sqrt ( ( - 2 * ( Z_tr @ Z_te . T ) . T + np . sum ( Z_tr * Z_tr , axis = 1 )) . T + np . sum ( Z_te * Z_te , axis = 1 ) ) # Figure out a way to read kernel type from M["kernel"]["k"] # Matern32 wb = np . sqrt ( 3.0 ) / theta [ 1 ] * wb # h in kernel_functions.jl wb = theta [ 0 ] * ( 1.0 + wb ) * np . exp ( - wb ) # Matern52 # wb = sqrt(5.) / theta[1] * wb # h in kernel_functions.jl # wb = theta[0] * (1. + wb + wb**2 / sqrt(3.)) * exp(-wb) # linear component to cross covariance matrix wb2 = theta [ 2 ] * Z_tr @ Z_te . T return ( wb + wb2 ) . T @ M_h def reduce_points ( points , Xproj_vectors , Xproj_values , Xmu , Xsigma ): [docs] Z = ( points - Xmu ) / Xsigma H = Xproj_vectors . T / Xproj_values return Z @ H class KernelFlowsRT ( RadiativeTransferEngine ): [docs] """ Radiative transfer emulation based on KernelFlows.jl and VSWIREmulator.jl. A description of the model can be found in: O. Lamminpää, J. Susiluoto, J. Hobbs, J. McDuffie, A. Braverman, and H. Owhadi. Forward model emulator for atmospheric radiative transfer using Gaussian processes and cross validation (2024). Submitted to Atmospheric Measurement Techniques. """ def __init__ ( self , engine_config : RadiativeTransferEngineConfig , ** kwargs ): # read VSWIREmulator struct from jld2 file into a dictionary self . f = self . h5_to_dict ( h5py . File ( engine_config . emulator_file , "r" )) self . emulator_wl = self . f [ "wls" ] self . emulator_internal_idx = self . f [ "inputdims" ] . astype ( int ) self . emulator_names = [ KEYMAPPING [ i ][ "name" ] for i in self . emulator_internal_idx ] self . points_bound_min = self . f [ "xmin" ] self . points_bound_max = self . f [ "xmax" ] with open ( engine_config . template_file , "r" ) as tpl_f : template = yaml . safe_load ( tpl_f ) try : # global KEYMAPPING KEYMAPPING [ 3 ][ "default" ] = template [ "MODTRAN" ][ 0 ][ "MODTRANINPUT" ][ "SURFACE" ][ "GNDALT" ] except : logging . info ( "No surface_elevation_km default in template" ) try : KEYMAPPING [ 4 ][ "default" ] = template [ "MODTRAN" ][ 0 ][ "MODTRANINPUT" ][ "GEOMETRY" ][ "H1ALT" ] except : logging . info ( "No observer_altitude_km default in template" ) try : KEYMAPPING [ 5 ][ "default" ] = template [ "MODTRAN" ][ 0 ][ "MODTRANINPUT" ][ "GEOMETRY" ][ "PARM2" ] except : logging . info ( "No solar_zenith default in template" ) try : # the KF emulator follows the MODTRAN convention for the view zenith KEYMAPPING [ 6 ][ "default" ] = template [ "MODTRAN" ][ 0 ][ "MODTRANINPUT" ][ "GEOMETRY" ][ "OBSZEN" ] except : logging . info ( "No observer_zenith default in template" ) try : KEYMAPPING [ 7 ][ "default" ] = template [ "MODTRAN" ][ 0 ][ "MODTRANINPUT" ][ "GEOMETRY" ][ "PARM1" ] except : logging . info ( "No relative_azimuth default in template" ) try : KEYMAPPING [ 9 ][ "default" ] = template [ "MODTRAN" ][ 0 ][ "MODTRANINPUT" ][ "GEOMETRY" ][ "TRUEAZ" ] except : logging . info ( "No observer_azimuth default in template" ) # defining some input transformations self . input_transfs = [ np . identity , np . log , lambda x : np . cos ( np . deg2rad ( x )), lambda x : np . cos ( np . deg2rad ( 90 - x )), lambda x : np . log ( 180 - x ), ] self . output_transfs = [ lambda x : x , lambda x : np . exp ( x ) - 0.1 , ] # Run super now....we need the lut_grid to go on super () . __init__ ( engine_config , ** kwargs ) # override default radiative transfer simulation mode # as KernelFlowsGP always runs in radiance space self . rt_mode = "rdn" self . assign_bounds () def assign_bounds ( self ): [docs] try : lut_grid_keynames = [ x for x in self . lut_grid . keys ()] self . point_inds_to_emulator_inds = np . array ( [ lut_grid_keynames . index ( i ) for i in self . emulator_names if i in lut_grid_keynames ] ) self . emulator_inds_to_point_inds = np . array ( [ self . emulator_names . index ( i ) for i in lut_grid_keynames if i in self . emulator_names ] ) logging . info ( f "lut_grid_keynames: { lut_grid_keynames } " ) logging . info ( f "emulator_names: { self . emulator_names } " ) logging . info ( f "point_inds_to_emulator_inds: { self . point_inds_to_emulator_inds } " ) logging . info ( f "emulator_inds_to_point_inds: { self . emulator_inds_to_point_inds } " ) except : outstr = "The provided emulator is missing lut keys: {[i for i in emulator_names if i not in self.lut_grid.keys()]}" raise ValueError ( outstr ) def h5_to_dict ( self , file ): [docs] outdict = {} for key , val in file . items (): if type ( val ) == h5py . _hl . dataset . Dataset : outdict [ key ] = np . array ( val ) else : outdict [ key ] = self . h5_to_dict ( val ) return outdict def preSim ( self ): [docs] # Track the KernelFlows directory used in the LUT attributes self . lut . setAttr ( "KernelFlows" , str ( self . engine_config . emulator_file )) logging . info ( f "KF Presim" ) self . srf_matrix = np . array ( [ spectral_response_function ( self . emulator_wl , wi , fwhmi / 2.355 ) for wi , fwhmi in zip ( self . wl , self . fwhm ) ] ) self . ga = list () default_lut_val = {} for key in self . emulator_internal_idx : logging . info ( KEYMAPPING [ key ]) default_lut_val [ KEYMAPPING [ key ][ "name" ]] = KEYMAPPING [ key ][ "default" ] self . default_fills = np . zeros ( len ( self . emulator_names )) for ii , key in enumerate ( self . emulator_names ): logging . info ( f "Checking key { key } " ) logging . info ( f "lut_grid keys: { self . lut_grid . keys () } " ) if key in self . lut_grid . keys (): self . default_fills [ ii ] = np . nan else : self . default_fills [ ii ] = default_lut_val [ key ] logging . info ( f "No grid point for { key } , using template: { self . default_fills [ ii ] } " ) self . assign_bounds () return False def makeSim ( self , point : np . array , template_only : bool = False ): [docs] # Kernel Flows doesn't need to make the simulation, as it can execute # directly pass def readSim ( self , in_point ): [docs] """Since KF doesn't need to run simulations, readSim is where we actually do the work Args: in_point (np.array): Input point - organized based on lut_grid, not emulator Returns: dict: Dictionary of output values """ np . set_printoptions ( suppress = True ) point = self . default_fills . copy () point [ self . emulator_inds_to_point_inds ] = in_point # observer zenith in LUT grid comes in ANG OBS file convention. # convert to MODTRAN convention as KF emulator is trained on that point [ self . emulator_names . index ( "observer_zenith" )] = ( 180 - point [ self . emulator_names . index ( "observer_zenith" )] ) if np . any ( point < self . points_bound_min ) or np . any ( point > self . points_bound_max ): fm_l = lambda x : np . round ( x , 4 ) outstr = f "Input point is out of bounds. 
 keys: { self . emulator_names } 
 point: { fm_l ( point ) } 
 xmin: { fm_l ( self . points_bound_min ) } 
 xmax: { fm_l ( self . points_bound_max ) } 
 oob_low: { point < self . points_bound_min } 
 oob_high: { point > self . points_bound_max } " raise ValueError ( outstr ) nMVMs = len ( self . f . keys ()) - 6 for i in range ( 1 , 1 + nMVMs ): MVM = self . predict_single_MVM ( self . f [ "MVM" + str ( i )], point , self . f [ "input_transfs" ][ i - 1 , :] ) self . ga . append ( MVM ) self . ga [ 1 ] = self . output_transfs [ 0 ]( self . ga [ 1 ][:, :]) self . ga [ 2 ] = self . output_transfs [ 0 ]( self . ga [ 2 ][:, :]) combined = { "rhoatm" : self . ga [ 0 ], "sphalb" : self . ga [ 3 ], "transm_down_dir" : self . ga [ 1 ], "transm_down_dif" : self . ga [ 2 ], "transm_up_dir" : np . zeros ( self . ga [ 0 ] . shape ), "transm_up_dif" : np . zeros ( self . ga [ 0 ] . shape ), "thermal_upwelling" : np . zeros ( self . ga [ 0 ] . shape ), "thermal_downwelling" : np . zeros ( self . ga [ 0 ] . shape ), "solar_irr" : np . zeros ( self . wl . shape ), } return combined def predict ( self , points ): [docs] if np . any ( points < self . points_bound_min ) or np . any ( points > self . points_bound_max ): outstr = f "Input points are out of bounds xmin: { self . points_bound_min } , xmax: { self . points_bound_max } " raise ValueError ( outstr ) nMVMs = len ( self . f . keys ()) - 6 for i in range ( 1 , 1 + nMVMs ): MVM = self . predict_single_MVM ( self . f [ "MVM" + str ( i )], points , self . f [ "input_transfs" ][ i - 1 , :] ) self . ga . append ( MVM ) # back-transform some quantities from log space # ToDo: this might not always be needed, # so we need an if-statement at some point ga_1 = self . output_transfs [ 0 ]( self . ga [ 1 ][:, :]) ga_2 = self . output_transfs [ 0 ]( self . ga [ 2 ][:, :]) combined = { "rhoatm" : self . ga [ 0 ], "sphalb" : self . ga [ 3 ], "transm_down_dir" : ga_1 , "transm_down_dif" : ga_2 , "transm_up_dir" : np . zeros ( self . ga [ 0 ] . shape ), "transm_up_dif" : np . zeros ( self . ga [ 0 ] . shape ), "thermal_upwelling" : np . zeros ( self . ga [ 0 ] . shape ), "thermal_downwelling" : np . zeros ( self . ga [ 0 ] . shape ), "solar_irr" : np . zeros ( self . wl . shape ), "wl" : self . wl , } return combined def predict_single_MVM ( self , MVM , points , transfs ): [docs] points = np . copy ( points ) # don't overwrite inputs if len ( points . shape ) == 1 : points = points . reshape ( 1 , - 1 ) for i , j in enumerate ( transfs ): if j == 1 : continue points [:, i ] = self . input_transfs [ j - 1 ]( points [:, i ]) nte = np . shape ( points )[ 0 ] nzycols = len ( MVM . keys ()) - 1 # take out GPGeometry from list of GPs ZY_pred = np . zeros (( nte , nzycols )) ZY_out = [] for i in range ( nzycols ): M = MVM [ "M" + str ( i + 1 )] G = MVM [ "G" ] # shorthand M_Z = np . array ( M [ "Z" ]) M_lambda = np . array ( M [ "lambda" ]) M_theta = np . array ( M [ "theta" ]) M_h = np . array ( M [ "h" ]) G_Xproj_vectors = np . array ( G [ "Xproj" + str ( i + 1 )][ "vectors" ]) G_Xproj_values = np . array ( G [ "Xproj" + str ( i + 1 )][ "values" ]) G_Xmean = np . array ( G [ "Xmean" ]) G_Xstd = np . array ( G [ "Xstd" ]) ZY_out . append ( predict_M ( M_Z , M_lambda , M_theta , M_h , points , G_Xproj_vectors , G_Xproj_values , G_Xmean , G_Xstd , ) ) for i in range ( len ( ZY_out )): ZY_pred [:, i ] = ZY_out [ i ] del ZY_out # H is same as in recover() in dimension_reduction.jl MP = self . srf_matrix @ G [ "Yproj" ][ "vectors" ][:, :] . T H = MP * G [ "Yproj" ][ "values" ][:] srfmean = self . srf_matrix @ G [ "Ymean" ] return ( ZY_pred @ H . T ) * G [ "Ystd" ] + srfmean
